function main (infile)
% ----------------------------------------------------------------------
%  MAIN PROGRAM - generated by the Rappture Builder
% ----------------------------------------------------------------------

% open the XML file containing the run parameters
% the file name comes in from the command-line via variable 'infile'
io = rpLib(infile);

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Get input values from Rappture
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% get input value for input.phase(welcome).note(intro)
intro = rpLibGetString(io,'input.phase(welcome).note(intro).current');

% get input value for input.phase(dimension).image(dev_geo)
% returns base64-encoded image data
dev_geo = rpLibGetString(io,'input.phase(dimension).image(dev_geo).current');

% get input value for input.phase(dimension).choice(TYPE)
TYPE = rpLibGetString(io,'input.phase(dimension).choice(TYPE).current');

% get input value for input.phase(dimension).number(lch) and convert to cm
str = rpLibGetString(io,'input.phase(dimension).number(lch).current');
[lch,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(dimension).number(lsd) and convert to cm
str = rpLibGetString(io,'input.phase(dimension).number(lsd).current');
[lsd,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(dimension).number(tch) and convert to cm
str = rpLibGetString(io,'input.phase(dimension).number(tch).current');
[tch,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(dimension).number(tox) and convert to cm
str = rpLibGetString(io,'input.phase(dimension).number(tox).current');
[tox,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(dimension).number(wch) and convert to cm
str = rpLibGetString(io,'input.phase(dimension).number(wch).current');
[wch,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(materials).number(eps_ox)
eps_ox = rpLibGetDouble(io,'input.phase(materials).number(eps_ox).current');

% get input value for input.phase(materials).number(eps_s)
eps_s = rpLibGetDouble(io,'input.phase(materials).number(eps_s).current');

% get input value for input.phase(materials).number(eps_d)
eps_d = rpLibGetDouble(io,'input.phase(materials).number(eps_d).current');

% get input value for input.phase(materials).number(eps_ch)
eps_ch = rpLibGetDouble(io,'input.phase(materials).number(eps_ch).current');

% get input value for input.phase(materials).number(N_s) and convert to cm-3
str = rpLibGetString(io,'input.phase(materials).number(N_s).current');
[N_s,err] = rpUnitsConvertDbl(str, 'cm-3');

% get input value for input.phase(materials).number(N_d) and convert to cm-3
str = rpLibGetString(io,'input.phase(materials).number(N_d).current');
[N_d,err] = rpUnitsConvertDbl(str, 'cm-3');

% get input value for input.phase(materials).number(N_ch) and convert to cm-3
str = rpLibGetString(io,'input.phase(materials).number(N_ch).current');
[N_ch,err] = rpUnitsConvertDbl(str, 'cm-3');

% get input value for input.phase(materials).number(Eg0_s) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(Eg0_s).current');
[Eg0_s,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(Eg0_d) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(Eg0_d).current');
[Eg0_d,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(Eg0_ch) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(Eg0_ch).current');
[Eg0_ch,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(E_s) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(E_s).current');
[E_s,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(E_d) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(E_d).current');
[E_d,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(X_s) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(X_s).current');
[X_s,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(X_d) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(X_d).current');
[X_d,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(X_ch) and convert to eV
str = rpLibGetString(io,'input.phase(materials).number(X_ch).current');
[X_ch,err] = rpUnitsConvertDbl(str, 'eV');

% get input value for input.phase(materials).number(N_T) and convert to cm-2
str = rpLibGetString(io,'input.phase(materials).number(N_T).current');
[N_T,err] = rpUnitsConvertDbl(str, 'cm-2');

% get input value for input.phase(fitting).group(fitting1).number(lambda_fit_s)
lambda_fit_s = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(lambda_fit_s).current');

% get input value for input.phase(fitting).group(fitting1).number(lambda_fit_d)
lambda_fit_d = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(lambda_fit_d).current');

% get input value for input.phase(fitting).group(fitting1).number(lambda_0_log_shift_s)
lambda_0_log_shift_s = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(lambda_0_log_shift_s).current');

% get input value for input.phase(fitting).group(fitting1).number(lambda_0_log_shift_d)
lambda_0_log_shift_d = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(lambda_0_log_shift_d).current');

% get input value for input.phase(fitting).group(fitting1).number(m_s)
m_s = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(m_s).current');

% get input value for input.phase(fitting).group(fitting1).number(m_d)
m_d = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(m_d).current');

% get input value for input.phase(fitting).group(fitting1).number(eta2_Jy_on)
eta2_Jy_on = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(eta2_Jy_on).current');

% get input value for input.phase(fitting).group(fitting1).number(eta2_Jy_amb)
eta2_Jy_amb = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(eta2_Jy_amb).current');

% get input value for input.phase(fitting).group(fitting1).number(sigma2_TGR_B2B_on)
sigma2_TGR_B2B_on = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(sigma2_TGR_B2B_on).current');

% get input value for input.phase(fitting).group(fitting1).number(sigma2_TGR_B2B_amb)
sigma2_TGR_B2B_amb = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(sigma2_TGR_B2B_amb).current');

% get input value for input.phase(fitting).group(fitting1).number(sigma2_TGR_TAT_on)
sigma2_TGR_TAT_on = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(sigma2_TGR_TAT_on).current');

% get input value for input.phase(fitting).group(fitting1).number(sigma2_TGR_TAT_amb)
sigma2_TGR_TAT_amb = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(sigma2_TGR_TAT_amb).current');

% get input value for input.phase(fitting).group(fitting1).number(f_Slope_TAT_on)
f_Slope_TAT_on = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(f_Slope_TAT_on).current');

% get input value for input.phase(fitting).group(fitting1).number(f_Slope_TAT_amb)
f_Slope_TAT_amb = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(f_Slope_TAT_amb).current');

% get input value for input.phase(fitting).group(fitting1).number(tau_on)
tau_on = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(tau_on).current');

% get input value for input.phase(fitting).group(fitting1).number(tau_amb)
tau_amb = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(tau_amb).current');

% get input value for input.phase(fitting).group(fitting1).number(Vfb) and convert to V
str = rpLibGetString(io,'input.phase(fitting).group(fitting1).number(Vfb).current');
[Vfb,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(fitting).group(fitting1).number(xmax_TAT)
xmax_TAT = rpLibGetDouble(io,'input.phase(fitting).group(fitting1).number(xmax_TAT).current');

% get input value for input.phase(fitting).group(fitting2).number(Vds_sat_on) and convert to V
str = rpLibGetString(io,'input.phase(fitting).group(fitting2).number(Vds_sat_on).current');
[Vds_sat_on,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(fitting).group(fitting2).number(A_Vds_sat)
A_Vds_sat = rpLibGetDouble(io,'input.phase(fitting).group(fitting2).number(A_Vds_sat).current');

% get input value for input.phase(fitting).group(fitting2).number(Vgs_sat_offset_on) and convert to V
str = rpLibGetString(io,'input.phase(fitting).group(fitting2).number(Vgs_sat_offset_on).current');
[Vgs_sat_offset_on,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(fitting).group(fitting2).number(Vgs_sat_offset_amb) and convert to V
str = rpLibGetString(io,'input.phase(fitting).group(fitting2).number(Vgs_sat_offset_amb).current');
[Vgs_sat_offset_amb,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(fitting).group(fitting2).number(A_Vgs)
A_Vgs = rpLibGetDouble(io,'input.phase(fitting).group(fitting2).number(A_Vgs).current');

% get input value for input.phase(fitting).group(fitting2).number(J_S_Diode) and convert to A/cm
str = rpLibGetString(io,'input.phase(fitting).group(fitting2).number(J_S_Diode).current');
[J_S_Diode,err] = rpUnitsConvertDbl(str, 'A/cm');

% get input value for input.phase(fitting).group(fitting2).number(n_diode)
n_diode = rpLibGetDouble(io,'input.phase(fitting).group(fitting2).number(n_diode).current');

% get input value for input.phase(fitting).group(fitting3).number(alpha)
alpha = rpLibGetDouble(io,'input.phase(fitting).group(fitting3).number(alpha).current');

% get input value for input.phase(fitting).group(fitting3).number(V0_gs) and convert to V
str = rpLibGetString(io,'input.phase(fitting).group(fitting3).number(V0_gs).current');
[V0_gs,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(fitting).group(fitting3).number(V0_gd) and convert to V
str = rpLibGetString(io,'input.phase(fitting).group(fitting3).number(V0_gd).current');
[V0_gd,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(fitting).group(fitting3).number(tdep) and convert to cm
str = rpLibGetString(io,'input.phase(fitting).group(fitting3).number(tdep).current');
[tdep,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(fitting).group(fitting3).number(Xb) and convert to cm
str = rpLibGetString(io,'input.phase(fitting).group(fitting3).number(Xb).current');
[Xb,err] = rpUnitsConvertDbl(str, 'cm');

% get input value for input.phase(fitting).group(fitting3).number(Cext)
Cext = rpLibGetDouble(io,'input.phase(fitting).group(fitting3).number(Cext).current');

% get input value for input.phase(fitting).group(fitting3).number(Covl)
Covl = rpLibGetDouble(io,'input.phase(fitting).group(fitting3).number(Covl).current');

% get input value for input.phase(Bias).group(transfer).boolean(plot_transfer)
str = rpLibGetString(io,'input.phase(Bias).group(transfer).boolean(plot_transfer).current');
plot_transfer = strcmpi(str,'yes');

% get input value for input.phase(Bias).group(transfer).boolean(plot_transfer_sep)
str = rpLibGetString(io,'input.phase(Bias).group(transfer).boolean(plot_transfer_sep).current');
plot_transfer_sep = strcmpi(str,'yes');

% get input value for input.phase(Bias).group(transfer).number(vds_t) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(transfer).number(vds_t).current');
[vds_t,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(transfer).number(vgs_min) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(transfer).number(vgs_min).current');
[vgs_min,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(transfer).number(vgs_max) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(transfer).number(vgs_max).current');
[vgs_max,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(transfer).number(dvgs) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(transfer).number(dvgs).current');
[dvgs,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(output).boolean(plot_out)
str = rpLibGetString(io,'input.phase(Bias).group(output).boolean(plot_out).current');
plot_out = strcmpi(str,'yes');

% get input value for input.phase(Bias).group(output).boolean(plot_out_sep)
str = rpLibGetString(io,'input.phase(Bias).group(output).boolean(plot_out_sep).current');
plot_out_sep = strcmpi(str,'yes');

% get input value for input.phase(Bias).group(output).number(vgs_o) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(output).number(vgs_o).current');
[vgs_o,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(output).number(vds_min) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(output).number(vds_min).current');
[vds_min,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(output).number(vds_max) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(output).number(vds_max).current');
[vds_max,err] = rpUnitsConvertDbl(str, 'V');

% get input value for input.phase(Bias).group(output).number(dvds) and convert to V
str = rpLibGetString(io,'input.phase(Bias).group(output).number(dvds).current');
[dvds,err] = rpUnitsConvertDbl(str, 'V');


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%  Add your code here for the main body of your program
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% path(path,'../src');

%% Device Parameters
global TFET_Para
TFET_Para.TYPE = str2num(TYPE);                % Choose TYPE: 1 = n-type, -1 = p-type
TFET_Para.lch = lch;                  % Channel length [cm]
TFET_Para.lsd = lsd;                  % Source/Drain length [cm]
TFET_Para.tch = tch;                  % Channel thickness [cm]
TFET_Para.tox = tox;                  % Gate-Oxide thickness [cm]
TFET_Para.wch = wch;                   % Channel width [cm]
TFET_Para.eps_ox = eps_ox * 8.854e-14;     % Permittivity oxide
TFET_Para.eps_s = eps_s * 8.854e-14;     % Permittivity source
TFET_Para.eps_d = eps_d * 8.854e-14;     % Permittivity drain
TFET_Para.eps_ch = eps_ch * 8.854e-14;    % Permittivity channel
TFET_Para.N_s = N_s;                   % Doping concentration Source [cm^-3]
TFET_Para.N_d = N_d;                   % Doping concentration Drain [cm^-3]
TFET_Para.N_ch = N_ch;               % Doping concentration Channel [cm^-3]    
TFET_Para.Eg0_s = Eg0_s;              % Bandgap Source [eV]
TFET_Para.Eg0_d = Eg0_d;              % Bandgap Drain [eV]
TFET_Para.Eg_ch = Eg0_ch;              % Bandgap Channel [eV]
TFET_Para.E_s = E_s;          % Degeneration within the source region [eV]
TFET_Para.E_d = E_d;               % Degeneration within the drain region [eV]
TFET_Para.X_s = X_s;                   % Affinity Source [eV]
TFET_Para.X_ch = X_ch;                  % Affinity Channel [eV]
TFET_Para.X_d = X_d;                   % Affinity Channel [eV]

TFET_Para.mat_s = string('Silicon');
TFET_Para.N_T = N_T;


%% Fitting Parameters
global TFET_Fit
TFET_Fit.m_s = m_s;    
TFET_Fit.m_d = m_d;   
TFET_Fit.eta2_Jy_on = eta2_Jy_on;
TFET_Fit.eta2_Jy_amb = eta2_Jy_amb;
TFET_Fit.sigma2_TGR_B2B_on  = sigma2_TGR_B2B_on;
TFET_Fit.sigma2_TGR_B2B_amb = sigma2_TGR_B2B_amb;
TFET_Fit.sigma2_TGR_TAT_on  = sigma2_TGR_TAT_on;
TFET_Fit.sigma2_TGR_TAT_amb = sigma2_TGR_TAT_amb;
TFET_Fit.tau_on = tau_on;
TFET_Fit.tau_amb = tau_amb;
TFET_Fit.f_Slope_TAT_on  = f_Slope_TAT_on; 
TFET_Fit.f_Slope_TAT_amb = f_Slope_TAT_amb;     
TFET_Fit.lambda_fit_s = lambda_fit_s; 
TFET_Fit.lambda_fit_d = lambda_fit_d; 
TFET_Fit.Vgs_sat_offset_on = Vgs_sat_offset_on; 
TFET_Fit.Vgs_sat_offset_amb = Vgs_sat_offset_amb;
TFET_Fit.A_Vgs = A_Vgs;
TFET_Fit.Vds_sat_on = Vds_sat_on; 
TFET_Fit.A_Vds_sat = A_Vds_sat;
TFET_Fit.lambda_0_log_shift_s = lambda_0_log_shift_s;
TFET_Fit.lambda_0_log_shift_d = lambda_0_log_shift_d;
TFET_Fit.Vfb = Vfb; 

TFET_Fit.N_ch = N_ch;            
TFET_Fit.Ninv_Vgs_eff = 1.6e19;   %% reference inversion charge for surface potential model (maybe additional fitting parameter)
TFET_Fit.xmax_TAT = xmax_TAT;
TFET_Fit.J_S_Diode = J_S_Diode;

TFET_Fit.n_diode = n_diode;
q = 1.602176634e-19;                  % Elementary charge [As]

%% Plot Properties
% global TFET_Plot_Prop

% TFET_Plot_Prop.LineWidth = 1.5;             % LineWidth



global TFET_Plot 

TFET_Plot.transfer_current              = 1;            % Plot transfer current on/off (1/0)
TFET_Plot.capacitances                  = 0;
TFET_Plot.transconductance              = 0;
TFET_Plot.second_derivative_transfer_curve = 0;
TFET_Plot.transfer_current_param_N_T    = 0;            % Plot transfer current on/off (1/0)
TFET_Plot.transfer_current_param_mat_s  = 0;            % Plot transfer current on/off (1/0)
TFET_Plot.transfer_current_param_tox    = 0;            % Plot transfer current on/off (1/0)
TFET_Plot.transfer_current_param_tch    = 0;
TFET_Plot.transfer_current_param_lch    = 0;
TFET_Plot.transfer_current_param_eps_ox = 0;
TFET_Plot.transfer_current_param_Nd     = 0;
TFET_Plot.transfer_current_param_Ns     = 0;
TFET_Plot.transfer_current_meas_NTFET   = 0;       % Plot transfer current on/off (1/0)
TFET_Plot.transfer_current_meas_PTFET   = 0;       % Plot transfer current on/off (1/0)
TFET_Plot.output_current                = 0;            % Plot output current on/off (1/0)
TFET_Plot.output_coductance             = 0;
TFET_Plot.potential                     = 0;            % Plot potential at x_pos on/off (1/0)
TFET_Plot.y_potential                   = 0;
TFET_Plot.bands                         = 0;            % Plot bands at y_pos on/off (1/0)
TFET_Plot.bands_GaAs                    = 0;            % Plot bands at y_pos on/off (1/0)
TFET_Plot.bands_SiliconGermanium        = 0;            % Plot bands at y_pos on/off (1/0)
TFET_Plot.bands_Germanium               = 0;            % Plot bands at y_pos on/off (1/0)
TFET_Plot.efield                        = 0;            % Plot efield at y_pos on/off (1/0)
TFET_Plot.Vgs_eff           = 0;            % Plot Vgs_eff in dependency of Vg on/off (1/0)
TFET_Plot.phi_center        = 0;            % Plot center potential in dependency of Vg on/off (1/0)
TFET_Plot.Vgs_eff_Vds_var   = 0;            % Plot Vgs_eff in dependency of Vg on/off (1/0)
TFET_Plot.phi_center_Vds_var= 0;            % Plot center potential in dependency of Vg on/off (1/0)
TFET_Plot.Phi_bi_eff_s      = 0;            % Plot effective built-in potential at source in dependency of Vg on/off (1/0)
TFET_Plot.Phi_bi_eff_d      = 0;            % Plot effective built-in potential at drain in dependency of Vg on/off (1/0)
TFET_Plot.TGR               = 0;
TFET_Plot.TGR_GaAs          = 0;
TFET_Plot.TGR_Germanium     = 0;
TFET_Plot.TGR_SiliconGermanium = 0;
TFET_Plot.Ttun              = 0;
TFET_Plot.Ttun_GaAs         = 0;
TFET_Plot.Ttun_Germanium    = 0;
TFET_Plot.Ttun_SiliconGermanium = 0;
TFET_Plot.potential_2D_ch   = 0;
TFET_Plot.second_derivative_output_curve = 0;
TFET_Plot.show_ambipolar_state = 1;
TFET_Plot.save              = 0;            % Save plots on/off (1/0)
TFET_Plot.save_csv          = 1;            % Save CSV on/off (1/0)
TFET_Plot.clear_plot        = 1;            % Clear plots on/off (1/0)

if 1
    TFET_Plot.y_pos     = string('Surface');    % Choose y-Position within channel (Surface/Center)
else
    TFET_Plot.y_pos   = string('Center');     % Choose y-Position within channel (Surface/Center)
end

if 0
    TFET_Plot.x_pos =  string('xch2');
elseif 0
    TFET_Plot.x_pos =  string('xjun_s');
else
    TFET_Plot.x_pos =  string('xjun_d');
end


% Prepare capacitance model
TYPE = TFET_Para.TYPE;
cdep =  eps_ch/tdep* 8.854e-14;
cox = eps_ox/tox* 8.854e-14;
cox1 = 1/(1/cox+1/cdep)+Covl/(lch-Xb);	% normalize Covl to (lch-Xb), because it will be multiplied with (lch-Xb)
delta_V = -0.001*TYPE;
Qi0 = q*TFET_Para.N_ch*tch;


rpUtilsProgress(5, 'Calculating transfer characteristics...');
if plot_transfer
	vg_t = (vgs_min:dvgs:vgs_max);
	vs = 0;
	vd = vds_t;
	for i = 1:length(vg_t)
		rpUtilsProgress((i/length(vg_t)*40), 'Calculating transfer characteristics...');
		TFET_result = func_TFET_verilog(vg_t(i), vd, vs,TFET_Para,TFET_Fit,TFET_Plot);
		Id_t(i) = TFET_result.Ids;
		Id_t_b2b(i) = TFET_result.Ids_B2B;
		Id_t_tat(i) = TFET_result.Ids_TAT;
		Id_t_diode(i) = TFET_result.Ids_diode;

		% capacitances:
		ids = abs(Id_t(i));
		result1 = fun_charge(TYPE*vg_t(i),TYPE*vd,TYPE*vs,V0_gd,V0_gs,tch,cox1,lch,Xb,wch,alpha,Qi0,TYPE,ids);
		Qch1_on = result1.Qch_on; 
		Qch1_ambi = result1.Qch_ambi;
		vd2 = vd-delta_V;
		[result2] = fun_charge(TYPE*vg_t(i),TYPE*vd2,TYPE*vs,V0_gd,V0_gs,tch,cox1,lch,Xb,wch,alpha,Qi0,TYPE,ids);
		Qch2_on = result2.Qch_on; 
		Qch2_ambi = result2.Qch_ambi;
		vs2 = vs - delta_V;
		[result3] = fun_charge(TYPE*vg_t(i),TYPE*vd,TYPE*vs2,V0_gd,V0_gs,tch,cox1,lch,Xb,wch,alpha,Qi0,TYPE,ids);
		Qch3_on = result3.Qch_on;
		Qch3_ambi = result3.Qch_ambi;
           	Cd_on(i) = 2*((Qch2_on - Qch1_on) )/(delta_V);		% Factor 2 for DG device
           	Cs_on(i) = 2*((Qch3_on - Qch1_on)/(delta_V));		% Factor 2 for DG device
           
           	Cd_ambi(i) = 2*(Qch1_ambi - Qch2_ambi ) /(delta_V);	% Factor 2 for DG device
           	Cs_ambi(i) = 2*(Qch3_ambi - Qch1_ambi)/(delta_V);	% Factor 2 for DG device
	   	Cs_t(i) = Cs_on(i) + Cs_ambi(i) + wch*Cext;
	   	Cd_t(i) = Cd_on(i) + Cd_ambi(i) + wch*Cext;
           
           	Cgg_t(i) = (Cd_on(i) + Cs_on(i) + Cd_ambi(i) + Cs_ambi(i))+(2*wch*Cext);
	end;
end;

if plot_out
	
	vd_o = vds_min:dvds:vds_max;
	vs = 0;
	vg = vgs_o;
	for i = 1:length(vd_o)
		rpUtilsProgress((45+i/length(vd_o)*40), 'Calculating output characteristics');
		TFET_result = func_TFET_verilog(vg, vd_o(i), vs,TFET_Para,TFET_Fit,TFET_Plot);
		Id_o(i) = TFET_result.Ids;
		Id_o_b2b(i) = TFET_result.Ids_B2B;
		Id_o_tat(i) = TFET_result.Ids_TAT;
		Id_o_diode(i) = TFET_result.Ids_diode;

		% capacitances
		ids = abs(Id_o(i));
		result1 = fun_charge(TYPE*vg,TYPE*vd_o(i),TYPE*vs,V0_gd,V0_gs,tch,cox1,lch,Xb,wch,alpha,Qi0,TYPE,ids);
		Qch1_on = result1.Qch_on; 
		Qch1_ambi = result1.Qch_ambi;
		vd2 = vd_o(i)-delta_V;
		[result2] = fun_charge(TYPE*vg,TYPE*vd2,TYPE*vs,V0_gd,V0_gs,tch,cox1,lch,Xb,wch,alpha,Qi0,TYPE,ids);
		Qch2_on = result2.Qch_on; 
		Qch2_ambi = result2.Qch_ambi;
		vs2 = vs - delta_V;
		[result3] = fun_charge(TYPE*vg,TYPE*vd_o(i),TYPE*vs2,V0_gd,V0_gs,tch,cox1,lch,Xb,wch,alpha,Qi0,TYPE,ids);
		Qch3_on = result3.Qch_on;
		Qch3_ambi = result3.Qch_ambi;
           	Cd_on(i) = 2*((Qch2_on - Qch1_on) )/(delta_V);		% Factor 2 for DG device
           	Cs_on(i) = 2*((Qch3_on - Qch1_on)/(delta_V));		% Factor 2 for DG device
           
           	Cd_ambi(i) = 2*(Qch1_ambi - Qch2_ambi ) /(delta_V);	% Factor 2 for DG device
           	Cs_ambi(i) = 2*(Qch3_ambi - Qch1_ambi)/(delta_V);	% Factor 2 for DG device
	   	Cs_o(i) = Cs_on(i) + Cs_ambi(i) + wch*Cext;
	   	Cd_o(i) = Cd_on(i) + Cd_ambi(i) + wch*Cext;
           
           	Cgg_o(i) = (Cd_on(i) + Cs_on(i) + Cd_ambi(i) + Cs_ambi(i))+(2*wch*Cext);
	end;
end;



